let state={page:'overview',step:1,file:false,mode:'split',selected:new Set(),allocations:{},readOnly:false,people:3000};
const titles={overview:['OPERATIONS OVERVIEW','触达工作台'],upload:['NEW IMPORT','上传白名单'],batches:['BATCH HISTORY','批次记录'],strategies:['STRATEGY MAPPING','策略配置']};
const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function go(page){state.page=page;$$('.page-view').forEach(x=>x.classList.toggle('active',x.id===`page-${page}`));$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$('#pageEyebrow').textContent=titles[page][0];$('#pageTitle').textContent=titles[page][1];window.scrollTo({top:0,behavior:'smooth'})}
$$('[data-goto]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.goto)));$$('.nav-item').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));
function statusTag(s){const c=s==='已完成'?'success':s==='执行中'?'processing':s==='待执行'?'warning':'failure';return `<span class="tag ${c}">${s}</span>`}
function batchRow(b){return `<tr><td><div class="batch-name"><strong>${b.id}</strong><span>${b.file}</span></div></td><td>${b.time}</td><td>${b.mode}</td><td>${b.strategies} 套</td><td>${b.people.toLocaleString()}</td><td>${b.records.toLocaleString()}</td><td class="progress-cell"><strong>${b.progress}%</strong><div class="progress-track"><i style="width:${b.progress}%"></i></div></td><td>${statusTag(b.status)}</td><td><button class="row-action" data-batch="${b.id}">详情</button></td></tr>`}
function renderBatches(){const q=$('#batchSearch')?.value.toLowerCase()||'';const f=$('#statusFilter')?.value||'all';const list=batches.filter(b=>(!q||(b.id+b.file).toLowerCase().includes(q))&&(f==='all'||b.status===f));$('#batchRows').innerHTML=list.map(batchRow).join('')||'<tr><td colspan="9">没有匹配的批次</td></tr>';$('#recentBatchRows').innerHTML=batches.slice(0,3).map(b=>`<tr><td><div class="batch-name"><strong>${b.id}</strong><span>${b.time}</span></div></td><td>${b.strategies} 套</td><td>${b.mode}</td><td>${b.people.toLocaleString()}</td><td class="progress-cell">${b.progress}%<div class="progress-track"><i style="width:${b.progress}%"></i></div></td><td>${statusTag(b.status)}</td><td><button class="row-action" data-batch="${b.id}">详情</button></td></tr>`).join('');$$('[data-batch]').forEach(x=>x.onclick=()=>openBatch(x.dataset.batch))}
function openBatch(id){const b=batches.find(x=>x.id===id);$('#dialogTitle').textContent=b.id;$('#dialogContent').innerHTML=`<div class="file-summary"><div class="file-badge">ZIP</div><div><strong>${b.file}</strong><span>${b.time} · 原始文件已销毁</span></div>${statusTag(b.status)}</div><div class="detail-metrics"><div><span>原始名单</span><strong>${b.people.toLocaleString()}</strong></div><div><span>执行记录</span><strong>${b.records.toLocaleString()}</strong></div><div><span>外呼接通率</span><strong>42.8%</strong></div><div><span>短信送达率</span><strong>96.2%</strong></div></div><div class="detail-tabs"><button class="active">执行概览</button><button>策略对比</button><button>联系人结果</button><button>回调日志</button></div><div class="preview-table"><table><thead><tr><th>策略</th><th>TIDE 任务 ID</th><th>分配人数</th><th>完成</th><th>结果</th></tr></thead><tbody><tr><td>三天触达 · 全 AI</td><td>TD-83A91F</td><td>${Math.ceil(b.people*.5).toLocaleString()}</td><td>${b.progress}%</td><td>${statusTag(b.status)}</td></tr><tr><td>单天触达 · 全 AI</td><td>TD-83A920</td><td>${Math.floor(b.people*.5).toLocaleString()}</td><td>${b.progress}%</td><td>${statusTag(b.status)}</td></tr></tbody></table></div>`;$('#batchDialog').showModal()}
$('#batchSearch').addEventListener('input',renderBatches);$('#statusFilter').addEventListener('change',renderBatches);
function renderStrategies(){const html=strategies.map((s,i)=>`<article class="strategy-card"><div class="strategy-card-top"><div class="strategy-icon">${String(i+1).padStart(2,'0')}</div><span class="status-toggle">已启用</span></div><h3>${s.name}</h3><div class="strategy-id">${s.id}</div><div class="strategy-tags"><span>${s.duration}</span><span>${s.rounds} 轮</span>${s.channels.map(c=>`<span>${c}</span>`).join('')}</div><p>${s.note}</p><div class="strategy-foot"><span>${s.env}环境</span><button class="edit-strategy">编辑映射</button></div></article>`).join('');$('#strategyGrid').innerHTML=html;$$('.edit-strategy').forEach(b=>b.onclick=()=>state.readOnly?toast('只读角色不能编辑策略'):toast('原型中保留当前策略配置'))}
function setFile(name='MX03-wl-260820.zip'){state.file=true;$('#fileName').textContent=name;$('#dropzone').classList.add('has-file');updateParse()}
$('#fileInput').addEventListener('change',e=>e.target.files[0]&&setFile(e.target.files[0].name));$('#loadSample').onclick=()=>{setFile();$('#password').value='7vuni9ev9e';updateParse();toast('已载入脱敏样例数据')};$('#password').addEventListener('input',updateParse);function updateParse(){$('#parseFile').disabled=!(state.file&&$('#password').value.trim())}
$('#showPassword').onclick=()=>{const p=$('#password');p.type=p.type==='password'?'text':'password';$('#showPassword').textContent=p.type==='password'?'显示':'隐藏'};
function step(n){state.step=n;$$('.wizard-step').forEach(x=>x.classList.toggle('active',x.id===`wizard-${n}`));$$('.step').forEach(x=>x.classList.toggle('active',Number(x.dataset.step)<=n));window.scrollTo({top:0,behavior:'smooth'})}
$('#parseFile').onclick=()=>{if(state.readOnly)return toast('只读角色不能上传名单');$('#parseFile').textContent='正在双层解密…';$('#parseFile').disabled=true;setTimeout(()=>{step(2);$('#parseFile').textContent='安全解析文件';toast('解析完成：3,000 条有效记录')},700)};$$('[data-next]').forEach(b=>b.onclick=()=>step(Number(b.dataset.next)));$$('[data-back]').forEach(b=>b.onclick=()=>step(Number(b.dataset.back)));
$$('input[name="duplicates"]').forEach(r=>r.onchange=()=>{$$('.radio-card').forEach(x=>x.classList.toggle('active',x.contains(r)&&r.checked));state.people=r.value==='exclude'?2816:3000;updateStrategySummary()});$('#downloadDuplicates').onclick=()=>toast('原型已模拟生成 184 条重复号码清单');
function renderStrategySelect(){const target=$('#strategySelectList');target.innerHTML=strategies.map((s,i)=>`<label class="strategy-choice" data-id="${s.id}"><input type="checkbox" value="${s.id}"><div><h4>${s.name}</h4><p>${s.id} · ${s.duration} · ${s.channels.join(' + ')}</p></div><div class="allocation"><input type="number" min="0" max="100" value="${i<2?50:0}" data-allocation="${s.id}"><span>%</span></div></label>`).join('');$$('.strategy-choice input[type="checkbox"]').forEach(c=>c.onchange=()=>{if(c.checked&&state.selected.size>=3){c.checked=false;return toast('一次最多选择 3 套策略')}c.checked?state.selected.add(c.value):state.selected.delete(c.value);c.closest('.strategy-choice').classList.toggle('selected',c.checked);updateStrategySummary()});$$('[data-allocation]').forEach(i=>i.oninput=()=>{state.allocations[i.dataset.allocation]=Number(i.value);updateStrategySummary()})}
$$('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;$$('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));$('#overlapWarning').classList.toggle('hidden',state.mode!=='overlap');$$('.allocation').forEach(x=>x.style.visibility=state.mode==='split'?'visible':'hidden');updateStrategySummary()});
function allocations(){const ids=[...state.selected];if(!ids.length)return{};let vals={};ids.forEach((id,i)=>vals[id]=state.allocations[id]??(i===0?50:i===1?50:0));return vals}
function updateStrategySummary(){const count=state.selected.size;const records=state.mode==='overlap'?state.people*Math.max(count,1):state.people;$('#modeSummary').textContent=state.mode==='split'?'名单分流':'同名单多策略';$('#peopleSummary').textContent=`${state.people.toLocaleString()} 人`;$('#recordSummary').textContent=`${records.toLocaleString()} 条`;$('#toConfirm').disabled=!count}
$('#toConfirm').onclick=()=>{const ids=[...state.selected];if(state.mode==='split'){const total=Object.values(allocations()).reduce((a,b)=>a+b,0);if(total!==100)return toast(`分流比例当前为 ${total}%，必须合计 100%`)}buildConfirm();step(4)};
function buildConfirm(){const records=state.mode==='overlap'?state.people*state.selected.size:state.people;$('#confirmPeople').textContent=`${state.people.toLocaleString()} 人`;$('#confirmMode').textContent=state.mode==='split'?'名单分流':'同名单多策略';$('#confirmRecords').textContent=`${records.toLocaleString()} 条`;const alloc=allocations();$('#confirmStrategyList').innerHTML=[...state.selected].map(id=>{const s=strategies.find(x=>x.id===id);const amount=state.mode==='overlap'?state.people:Math.round(state.people*(alloc[id]||0)/100);return `<div class="confirm-strategy-row"><div><strong>${s.name}</strong><br><span>${s.id}</span></div><strong>${amount.toLocaleString()} 人</strong></div>`}).join('');$('#riskConfirm').classList.toggle('hidden',state.mode!=='overlap');updateSubmit()}
function updateSubmit(){const common=$('#submitCheckbox').checked;const risk=state.mode!=='overlap'||$('#riskCheckbox').checked;$('#submitBatch').disabled=!(common&&risk)}$('#submitCheckbox').onchange=updateSubmit;$('#riskCheckbox').onchange=updateSubmit;$('#submitBatch').onclick=()=>{batches.unshift({id:'MX03-20261016-004',file:'MX03-wl-260820.zip',time:'刚刚',mode:state.mode==='split'?'名单分流':'同名单多策略',strategies:state.selected.size,people:state.people,records:state.mode==='overlap'?state.people*state.selected.size:state.people,progress:0,status:'待执行'});renderBatches();$$('.wizard-step').forEach(x=>x.classList.remove('active'));$('#wizard-success').classList.add('active');toast('批次创建成功，原始文件已标记销毁')};
$('#newUpload').onclick=()=>{state={...state,step:1,file:false,selected:new Set(),allocations:{},mode:'split',people:3000};$('#password').value='';$('#fileName').textContent='拖放 ZIP 文件到这里';$('#dropzone').classList.remove('has-file');$('#submitCheckbox').checked=false;$('#riskCheckbox').checked=false;renderStrategySelect();step(1)};
$('#roleToggle').onclick=()=>{state.readOnly=!state.readOnly;$('#roleText').textContent=state.readOnly?'只读查看者':'Admin';$('#addStrategy').disabled=state.readOnly;toast(state.readOnly?'已切换为只读视图':'已切换为 Admin')};
$('#addStrategy').onclick=()=>state.readOnly?toast('只读角色不能新增策略'):$('#strategyDialog').showModal();$$('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#strategyForm').onsubmit=e=>{e.preventDefault();strategies.push({name:$('#strategyName').value,id:$('#strategyId').value,duration:$('#strategyDuration').value,channels:$('#strategyChannels').value.split('+').map(x=>x.trim()),rounds:0,note:$('#strategyNote').value||'由 TIDE 管理内部执行规则。',env:$('#strategyEnv').value});renderStrategies();renderStrategySelect();$('#strategyDialog').close();e.target.reset();toast('策略映射已保存')};
renderBatches();renderStrategies();renderStrategySelect();
